import * as React from "react";

export type MoonNewIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function MoonNewIcon({ size = 20, ...props }: MoonNewIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="12" r="7.5"/><path d="M7 12h10"/>
    </svg>
  );
}
